-- Phase 1 / Core Multi-Tenant, Branch, RBAC, Session & Audit Foundation Schema
-- PostgreSQL 15+ compatible; UUID primary keys generated by application (UUIDv7) or gen_random_uuid().

CREATE TABLE tenants (
    id              UUID PRIMARY KEY,
    code            VARCHAR(64)  NOT NULL UNIQUE,
    legal_name      VARCHAR(200) NOT NULL,
    display_name    VARCHAR(200) NOT NULL,
    default_currency CHAR(3)     NOT NULL DEFAULT 'USD',
    status          VARCHAR(32)  NOT NULL DEFAULT 'ACTIVE',
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version         BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT chk_tenants_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'ARCHIVED'))
);

CREATE TABLE branches (
    id              UUID PRIMARY KEY,
    tenant_id       UUID         NOT NULL REFERENCES tenants(id),
    code            VARCHAR(64)  NOT NULL,
    name            VARCHAR(200) NOT NULL,
    timezone        VARCHAR(64)  NOT NULL DEFAULT 'UTC',
    currency_code   CHAR(3)      NOT NULL DEFAULT 'USD',
    active          BOOLEAN      NOT NULL DEFAULT TRUE,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version         BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_branches_tenant_code UNIQUE (tenant_id, code)
);

CREATE INDEX idx_branches_tenant ON branches (tenant_id);

CREATE TABLE terminals (
    id              UUID PRIMARY KEY,
    tenant_id       UUID         NOT NULL REFERENCES tenants(id),
    branch_id       UUID         NOT NULL REFERENCES branches(id),
    terminal_code   VARCHAR(64)  NOT NULL,
    display_name    VARCHAR(120) NOT NULL,
    os_platform     VARCHAR(32)  NOT NULL,
    secret_hash     VARCHAR(255) NOT NULL,
    active          BOOLEAN      NOT NULL DEFAULT TRUE,
    last_seen_at    TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version         BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_terminals_branch_code UNIQUE (tenant_id, branch_id, terminal_code)
);

CREATE INDEX idx_terminals_tenant_branch ON terminals (tenant_id, branch_id);

CREATE TABLE users (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID         NOT NULL REFERENCES tenants(id),
    username            VARCHAR(100) NOT NULL,
    full_name           VARCHAR(200) NOT NULL,
    email               VARCHAR(200),
    password_hash       VARCHAR(255) NOT NULL,
    pin_hash            VARCHAR(255),
    active              BOOLEAN      NOT NULL DEFAULT TRUE,
    failed_login_count  INT          NOT NULL DEFAULT 0,
    locked_until        TIMESTAMPTZ,
    last_login_at       TIMESTAMPTZ,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version             BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_users_tenant_username UNIQUE (tenant_id, username),
    CONSTRAINT chk_users_failed_login_non_neg CHECK (failed_login_count >= 0)
);

CREATE INDEX idx_users_tenant_active ON users (tenant_id, active);

CREATE TABLE roles (
    id              UUID PRIMARY KEY,
    tenant_id       UUID         NOT NULL REFERENCES tenants(id),
    code            VARCHAR(64)  NOT NULL,
    name            VARCHAR(120) NOT NULL,
    description     VARCHAR(500),
    system_template BOOLEAN      NOT NULL DEFAULT FALSE,
    max_discount_pct NUMERIC(5,2) NOT NULL DEFAULT 0.00,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    version         BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT uq_roles_tenant_code UNIQUE (tenant_id, code),
    CONSTRAINT chk_roles_discount_pct CHECK (max_discount_pct >= 0.00 AND max_discount_pct <= 100.00)
);

CREATE TABLE permissions (
    id              UUID PRIMARY KEY,
    code            VARCHAR(100) NOT NULL UNIQUE,
    module          VARCHAR(64)  NOT NULL,
    description     VARCHAR(300) NOT NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE TABLE role_permissions (
    role_id         UUID        NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    permission_id   UUID        NOT NULL REFERENCES permissions(id) ON DELETE RESTRICT,
    granted_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE user_branch_access (
    user_id         UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    branch_id       UUID        NOT NULL REFERENCES branches(id) ON DELETE CASCADE,
    tenant_id       UUID        NOT NULL REFERENCES tenants(id),
    granted_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (user_id, branch_id)
);

CREATE INDEX idx_user_branch_access_branch ON user_branch_access (tenant_id, branch_id);

CREATE TABLE user_role_assignments (
    id              UUID PRIMARY KEY,
    tenant_id       UUID        NOT NULL REFERENCES tenants(id),
    user_id         UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role_id         UUID        NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    branch_id       UUID        REFERENCES branches(id) ON DELETE CASCADE,
    assigned_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_user_role_scope UNIQUE NULLS NOT DISTINCT (user_id, role_id, branch_id)
);

CREATE INDEX idx_user_role_assignments_lookup ON user_role_assignments (tenant_id, user_id, branch_id);

CREATE TABLE user_sessions (
    id              UUID PRIMARY KEY,
    tenant_id       UUID         NOT NULL REFERENCES tenants(id),
    branch_id       UUID         REFERENCES branches(id),
    user_id         UUID         NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    terminal_id     UUID         REFERENCES terminals(id),
    token_hash      VARCHAR(255) NOT NULL UNIQUE,
    expires_at      TIMESTAMPTZ  NOT NULL,
    revoked_at      TIMESTAMPTZ,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_user_sessions_user_active ON user_sessions (user_id, expires_at) WHERE revoked_at IS NULL;

CREATE TABLE audit_logs (
    id                  UUID PRIMARY KEY,
    tenant_id           UUID         NOT NULL REFERENCES tenants(id),
    branch_id           UUID         REFERENCES branches(id),
    actor_user_id       UUID         REFERENCES users(id),
    action              VARCHAR(64)  NOT NULL,
    target_entity_type  VARCHAR(80),
    target_entity_id    VARCHAR(120),
    details_json        JSONB,
    correlation_id      VARCHAR(64)  NOT NULL,
    occurred_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_audit_logs_tenant_branch_time ON audit_logs (tenant_id, branch_id, occurred_at DESC);
CREATE INDEX idx_audit_logs_correlation ON audit_logs (correlation_id);
